local name = 'ZCJMedicalDeploymentVerify'
hook.Add('InitPostEntity', name, function()
    hook.Remove('InitPostEntity', name)
    local attempts = 0
    timer.Create(name, 1, 15, function()
        attempts = attempts + 1
        local ok, result = pcall(function()
            return include('zc_justice_v3/deployment_verify.lua').check(expected)
        end)
        file.CreateDir('zc_justice_v3_shadow')
        if ok then
            file.Write('zc_justice_v3_shadow/medical_startup_verified.json', util.TableToJSON(result, true))
            timer.Remove(name)
        elseif attempts == 15 then
            file.Write('zc_justice_v3_shadow/medical_startup_verified.json', util.TableToJSON({
                passed=false, version=expected.version, deployment_id=expected.deployment_id,
                time=os.time(), enforcement=false, error=tostring(result)}, true))
